// Team gold item: per-agent expectations + forbiddens (plain JS)
const teamGold = {
  id: "t4", kind: "edge",
  ticket: "Sneakers 3 weeks late AND I want a refund.",
  expect: {
    triage: { category: "shipping" },
    decider: { approved: false, reasonPresent: true },
    draft: { maxWords: 60 },
  },
  forbid: ["direct-refund", "unvalidated-category"],
};
// Runner checks each slot against the attributed agent's outputs.

// Attribution checker: per-agent slots + forbiddens (plain JS)
function checkTeamRun(result, gold) {
  const issues = [];
  for (const [agent, exp] of Object.entries(gold.expect)) {
    const got = result[agent] || {};
    for (const [k, v] of Object.entries(exp)) {
      const ok = typeof v === "boolean" ? !!got[k] === v : got[k] === v;
      if (!ok) issues.push(`${agent}.${k}: expected ${JSON.stringify(v)}`);
    }
  }
  for (const f of gold.forbid || [])
    if (JSON.stringify(result).includes(f)) issues.push("forbidden:" + f);
  return { pass: issues.length === 0, issues };
}
